function bindVolume(input){
 input.dataset.mirrorControl='true';let before=null,epoch=0;
 const blocked=()=>stateSaveSuspended||root.mygrainSongBeta?.playing||root.mygrainCardHistory?.busy;
 const begin=()=>{if(!blocked()){before=state.level;epoch=generation;}};
 input.addEventListener('pointerdown',begin);input.addEventListener('keydown',event=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End','PageUp','PageDown'].includes(event.key))begin();});
 input.addEventListener('input',()=>{if(blocked()||(before!==null&&epoch!==generation)){before=null;syncVolume();return;}if(before===null)begin();state.level=Math.max(0,Math.min(1,Number(input.value)/100));update();});
 input.addEventListener('change',()=>{if(before===null||epoch!==generation||blocked()){before=null;syncVolume();return;}const after=state.level;state.level=before;before=null;update();edit('volume',()=>{state.level=after;update();});});
 input.addEventListener('pointercancel',()=>{if(before!==null&&epoch===generation){state.level=before;update();}before=null;syncVolume();});
}
function syncPower(){$('emberPower').textContent=state.enabled?'E On':'E Off';$('emberPower').setAttribute('aria-pressed',String(state.enabled));$('emberPlay').textContent=graph?'Stop':'Play';if($('emberLayerPower')){$('emberLayerPower').textContent=state.enabled?'E On':'E Off';$('emberLayerPower').setAttribute('aria-pressed',String(state.enabled));}for(const id of ['emberSolo','emberLayerSolo']){const b=$(id);if(b){const solo=hasLoopLayerSolo('bastarde');b.textContent=solo?'Solo On':'Solo Off';b.setAttribute('aria-pressed',String(solo));b.classList.toggle('active',solo);}}$('emberLayerPower')?.classList.toggle('layer-muted',!state.enabled);card.dataset.active=String(state.enabled);syncVolume();syncBastardLoopUi();}
function stop(){if(route){route.disconnect();route=null;}graph?.dispose();graph=null;origin=null;syncPower();}
function start(at=null){
 stop();if(!state.enabled||!audioContext||!preFilterGainNode)return false;
 const time=Number.isFinite(at)?at:audioContext.currentTime+.025;origin=getSharedLoopTransportOriginTime()??time;
 const destination=audioContext.createGain();destination.gain.value=1;
 // The existing source-owned router provides Whole mix insert / DAW / Solo policies.
 route=root.mygrainCharacterFx.connect('E',destination,preFilterGainNode,null,audioContext);
 const link=route;route={disconnect(){link.disconnect();destination.disconnect();}};
 graph=M.createGraph(audioContext,destination,state,{time,origin,bpm:getTransportClockBpm(),gate});syncPower();status('Ember playing · '+state.cables.length+' bridges.');return true;
}
function set(value,{save=false,replace=false}={}){state=M.normalize({...(!replace?state:{}),...value});if(!state.enabled)stop();else if(graph)update();else if(bastardLoopPlaying||(!root.__mygrainSongRenderDeck&&sequencerPlaying))start();sync();if(save)saveState();}
function sync(){syncDividers();syncPower();clock();syncPreset();syncLfo();syncCrossMod();syncNoteTunings();$('emberWave').value=state.wave;$('emberPulseRate').value=state.pulseRate;for(const d of card.querySelectorAll('[data-knob]'))syncKnob(d);syncPulses(true);syncCables();}
